%% htag.sty -- permanent margin tags for theorem-like environments,
%% computed from their labels.
%%
%% Usage (preamble):
%%   \usepackage{htag}
%%   \htagsalt{my-document}
%%   \htagenvironments{theorem,lemma,proposition,corollary,definition}
%%
%% Every listed environment must carry a \label (compiling stops with an
%% error at its \end otherwise) and gets a 4-character tag in the margin.
%% The tag is computed from the label: read the MD5 digest of
%% "<salt>:<label>" as a number, reduce it modulo 34^4 and write the result
%% in base 34, least significant digit first, with the alphabet
%% 0123456789ABCDEFGHJKLMNPQRSTUVWXYZ (no I and no O). So the tag is the
%% same on every run, engine and machine; it does not change when items are
%% added, moved or renumbered; and it differs between documents with
%% different salts. Use a new salt for each document and never change it.
%%
%% Two labels can get the same tag. Compiling then stops with an error that
%% names both and suggests a free tag; pin it on one of them with \htag.
%%
%% htag-registry.tex records the salt and every tag the document has shown,
%% with its label, sorted by tag. Commit it with your sources and never edit
%% it. Tags do not depend on it: without it they come out the same. It is a
%% check: compiling stops with an error if the salt has changed, if a label
%% has a different tag than before, or if a new label gets the tag of a
%% deleted one. A run with a htag error does not rewrite the registry.
%%
%% htag-index.md is rewritten on every compile: a table of the tags in the
%% document now, with environment, printed number, page, label and
%% file:line, for looking a tag up. It is a disposable snapshot.
%%
%% \htag{XXXX}  inside a listed environment (put it right after \begin):
%%              pins that environment's tag, e.g. to keep a tag assigned by
%%              hand or by an earlier scheme; such an environment needs no
%%              \label. Anywhere else: prints XXXX in the margin, e.g. right
%%              after a section heading (not inside its title, which is
%%              also typeset in the table of contents). \htag{} does nothing.
%%
%% Environments must be opened with \begin...\end: thmtools' restatable,
%% which calls the environment's macros directly, gets no tag. Inside a
%% float or a minipage no margin note can go; such an item gets its tag and
%% registry entry, with a warning, but the tag is not printed.
%% \htagsalt{salt}      the salt of this document (preamble only; required).
%% \htagmark            the tag as printed in the margin; \renewcommand it to
%%                      restyle. htag.sty sets it in an \hbox inside a
%%                      \marginpar, so it cannot start a paragraph there.
%% \htagregistry{file}  use another registry file name (preamble only).
%% \htagindex{file}     use another index file name (preamble only).

\NeedsTeXFormat{LaTeX2e}[2022-06-01]
\ProvidesExplPackage{htag}{2026-10-16}{1.0}
  {Permanent margin tags for theorem-like environments, computed from labels}

% ---------------------------------------------------------------- settings

\str_new:N \g__htag_salt_str
\str_new:N \g__htag_file_str
\str_gset:Nn \g__htag_file_str { htag-registry.tex }
\str_new:N \g__htag_index_str
\str_gset:Nn \g__htag_index_str { htag-index.md }
\str_new:N \g__htag_main_str          % name of the main .tex file
% 34 symbols: I and O are left out because they look like 1 and 0
\str_const:Nn \c__htag_alphabet_str { 0123456789ABCDEFGHJKLMNPQRSTUVWXYZ }
\int_const:Nn \c__htag_base_int { 34 }
\int_const:Nn \c__htag_digits_int { 4 }
\int_const:Nn \c__htag_modulus_int { 1336336 }   % 34^4

% ---------------------------------------------------------------- state

% linked property lists (kernel 2024-02 and later) take constant time per
% access; flat ones take time proportional to their length
\cs_if_exist:NTF \prop_new_linked:N
  { \cs_new_eq:NN \__htag_prop_new:N \prop_new_linked:N }
  { \cs_new_eq:NN \__htag_prop_new:N \prop_new:N }

% the registry as read at \begin{document}
\str_new:N  \g__htag_reg_salt_str
\__htag_prop_new:N \g__htag_reg_tag_prop     % label -> tag
\__htag_prop_new:N \g__htag_reg_labels_prop  % tag -> {label}{label}... ({} for no label)
\seq_new:N  \g__htag_entries_seq      % registry lines {tag}{label}, old and new
\bool_new:N \g__htag_found_bool       % registry file existed
\bool_new:N \g__htag_changed_bool     % registry must be rewritten
\bool_new:N \g__htag_error_bool       % a htag error happened in this run
\bool_new:N \g__htag_rerun_bool
\bool_new:N \g__htag_listed_bool      % \htagenvironments was used
% the last run, from the .aux file
\__htag_prop_new:N \g__htag_byocc_prop       % environment no. -> its tag
\__htag_prop_new:N \g__htag_bylabel_prop     % label -> its tag
\__htag_prop_new:N \g__htag_page_prop        % item -> page
% this run
\int_new:N  \g__htag_occ_int          % listed environments seen
\__htag_prop_new:N \g__htag_label_prop       % environment no. -> its \label
\__htag_prop_new:N \g__htag_pinned_prop      % environment no. -> its \htag{...}
\__htag_prop_new:N \g__htag_where_prop       % environment no. -> 'lemma on input line N'
\__htag_prop_new:N \g__htag_shown_prop       % environment no. -> tag typeset
\__htag_prop_new:N \g__htag_runin_prop       % environment no. -> {} if it follows a run-in heading
\__htag_prop_new:N \g__htag_level_prop       % environment no. -> TeX group level inside it
\__htag_prop_new:N \g__htag_boxed_prop       % environment no. -> {} if inside a float or minipage
\__htag_prop_new:N \g__htag_claimer_prop     % tag -> label of the item that has it in this run
\__htag_prop_new:N \g__htag_doclabels_prop   % label -> {} for every item label of this run
\seq_new:N  \g__htag_envs_seq               % the listed environments
\int_new:N  \l__htag_level_int              % group level inside the innermost listed environment
\tl_const:Nn \c__htag_footnote_tl { footnote }
\__htag_prop_new:N \g__htag_final_prop       % item -> tag
\__htag_prop_new:N \g__htag_inrun_prop       % tag -> where it appears
\__htag_prop_new:N \g__htag_used_prop        % tag -> {} for every tag of this run
\tl_new:N   \l__htag_current_tl       % no. of the innermost listed environment
\tl_new:N   \l__htag_env_tl           % and its name
\tl_new:N   \l__htag_tag_tl
\tl_new:N   \l__htag_label_tl
\tl_new:N   \l__htag_where_tl
\tl_new:N   \l__htag_owners_tl
\tl_new:N   \l__htag_free_tl
\tl_new:N   \l__htag_other_tl
\tl_new:N   \l__htag_key_tl
\tl_new:N   \l__htag_tmp_tl
\str_new:N  \l__htag_hex_str
\int_new:N  \l__htag_n_int
\int_new:N  \l__htag_k_int
\bool_new:N \l__htag_bad_bool
\bool_new:N \l__htag_pinned_bool
\bool_new:N \l__htag_dup_bool
\iow_new:N  \g__htag_iow
% for the index; an item is an environment no., or s<k> for the k-th
% \htag outside listed environments
\seq_new:N  \g__htag_items_seq        % items in document order
\seq_new:N  \g__htag_files_seq        % stack of files being read
\seq_new:N  \g__htag_rows_seq
\__htag_prop_new:N \g__htag_envname_prop     % item -> environment
\__htag_prop_new:N \g__htag_number_prop      % item -> printed number
\__htag_prop_new:N \g__htag_source_prop      % item -> file:line
\int_new:N  \g__htag_free_int
\tl_new:N   \l__htag_item_tl
\tl_new:N   \l__htag_prevlabel_tl     % \@currentlabel before the environment
\tl_new:N   \l__htag_prevcounter_tl   % \@currentcounter before the environment
\int_new:N  \l__htag_wa_int
\int_new:N  \l__htag_wb_int
\int_new:N  \l__htag_wc_int
\int_new:N  \l__htag_wd_int
\int_new:N  \l__htag_we_int
\int_new:N  \l__htag_wf_int
\providecommand \@currentcounter {}

\cs_generate_variant:Nn \prop_gput:Nnn { NVn , NVx , Nxx , Nnx , NnV , NVV }
\cs_generate_variant:Nn \prop_gremove:Nn { NV }
\cs_generate_variant:Nn \prop_item:Nn { NV }
\prg_generate_conditional_variant:Nnn \prop_get:NnN { NV } { T , F , TF }
\prg_generate_conditional_variant:Nnn \prop_if_in:Nn { NV } { p , T , F , TF }
\cs_generate_variant:Nn \msg_warning:nnn { nnx }
\cs_generate_variant:Nn \msg_warning:nnnn { nnxx }
\cs_generate_variant:Nn \msg_warning:nnnnn { nnxxx }

% ---------------------------------------------------------------- messages

\msg_new:nnnn { htag } { no-salt }
  { No~\iow_char:N\\htagsalt~is~set. }
  {
    Put~\iow_char:N\\htagsalt\iow_char:N\{<name~of~this~document>\iow_char:N\}~
    in~the~preamble.~Use~a~new~salt~for~each~document~and~never~change~it.
  }
\msg_new:nnnn { htag } { salt-changed }
  { The~salt~is~'#1',~but~#2~was~made~with~'#3'.~A~new~salt~changes~every~tag. }
  { Restore~\iow_char:N\\htagsalt\iow_char:N\{#3\iow_char:N\}. }
\msg_new:nnnn { htag } { no-label }
  {
    #1~has~no~\iow_char:N\\label.~Every~environment~listed~in~
    \iow_char:N\\htagenvironments~needs~one,~because~its~tag~is~computed~from~it.
  }
  { Add~\iow_char:N\\label\iow_char:N\{...\iow_char:N\}~inside~the~environment,~before~its~\iow_char:N\\end. }
\msg_new:nnnn { htag } { duplicate }
  { Tag~'#1'~appears~twice:~#2~and~#3. }
  {
    Pin~a~free~tag~on~#3,~e.g.~\iow_char:N\\htag\iow_char:N\{#4\iow_char:N\}~
    right~after~its~\iow_char:N\\begin.
  }
\msg_new:nnnn { htag } { changed }
  { #1~gets~tag~'#2',~but~its~label~had~tag~'#3'~before.~Tags~never~change. }
  { Keep~the~old~tag~with~\iow_char:N\\htag\iow_char:N\{#3\iow_char:N\}. }
\msg_new:nnnn { htag } { retired }
  { #1~gets~tag~'#2',~which~#3~had~before.~Tags~are~never~reused. }
  { Pin~a~free~tag~on~it,~e.g.~\iow_char:N\\htag\iow_char:N\{#4\iow_char:N\}. }
\msg_new:nnnn { htag } { reused }
  { Tag~'#1'~belongs~to~#2~and~cannot~be~used~by~#3. }
  { Choose~another~tag,~e.g.~'#4'. }
\msg_new:nnn { htag } { takeover }
  { #1~takes~over~tag~'#2'~from~#3. }
\msg_new:nnn { htag } { not-shown }
  { #1~is~inside~a~float~or~minipage,~where~no~margin~note~can~go;~its~tag~'#2'~is~not~shown. }
\msg_new:nnn { htag } { bad-form }
  { Tag~'#1'~(#2)~is~not~four~characters~from~0-9~and~A-Z~without~I~and~O. }
\msg_new:nnn { htag } { rerun }
  { Tags~have~changed.~Rerun~to~get~them~right. }
\msg_new:nnn { htag } { new-registry }
  { Created~#1.~Commit~it~with~your~sources;~it~is~what~stops~tags~being~reused. }

% every error goes through here, so that the registry is not rewritten
\cs_new_protected:Npn \__htag_error:nnnnn #1#2#3#4#5
  {
    \bool_gset_true:N \g__htag_error_bool
    \msg_error:nnnnnn { htag } {#1} {#2} {#3} {#4} {#5}
  }
\cs_generate_variant:Nn \__htag_error:nnnnn { nxxxx }

% ---------------------------------------------------------------- tags

% the tag of the string #1, into token list #2
\cs_new_protected:Npn \__htag_hash:nN #1#2
  {
    \str_set:Nx \l__htag_hex_str { \str_mdfive_hash:n {#1} }
    \int_zero:N \l__htag_n_int
    \str_map_inline:Nn \l__htag_hex_str
      {
        \int_set:Nn \l__htag_n_int
          {
            \int_mod:nn { \l__htag_n_int * 16 + \int_from_hex:n {##1} }
              { \c__htag_modulus_int }
          }
      }
    \tl_clear:N #2
    \prg_replicate:nn { \c__htag_digits_int }
      {
        \tl_put_right:Nx #2
          {
            \str_item:Nn \c__htag_alphabet_str
              { \int_mod:nn { \l__htag_n_int } { \c__htag_base_int } + 1 }
          }
        \int_set:Nn \l__htag_n_int
          { \int_div_truncate:nn { \l__htag_n_int } { \c__htag_base_int } }
      }
  }
\cs_generate_variant:Nn \__htag_hash:nN { xN }

% the tag of label #1, into token list #2
\cs_new_protected:Npn \__htag_tag_of:nN #1#2
  { \__htag_hash:xN { \g__htag_salt_str \c_colon_str \tl_to_str:n {#1} } #2 }
\cs_generate_variant:Nn \__htag_tag_of:nN { VN }

% a free tag for an item with key #1 (its label, or where it is), into #2:
% the tag of "<salt>:<key>:<k>" for the least k for which it is free
\cs_new_protected:Npn \__htag_free_tag:nN #1#2
  {
    \int_zero:N \l__htag_k_int
    \bool_do_until:nn
      {
        ! \prop_if_in_p:NV \g__htag_used_prop #2
        && ! \prop_if_in_p:NV \g__htag_reg_labels_prop #2
      }
      {
        \int_incr:N \l__htag_k_int
        \__htag_hash:xN
          {
            \g__htag_salt_str \c_colon_str \tl_to_str:n {#1}
            \c_colon_str \int_use:N \l__htag_k_int
          }
          #2
      }
  }
\cs_generate_variant:Nn \__htag_free_tag:nN { VN }

% warn if a tag written by hand is not 4 symbols of the alphabet
\cs_new_protected:Npn \__htag_check_form:nn #1#2
  {
    \bool_set_false:N \l__htag_bad_bool
    \int_compare:nNnF { \str_count:n {#1} } = \c__htag_digits_int
      { \bool_set_true:N \l__htag_bad_bool }
    \str_map_inline:nn {#1}
      { \tl_if_in:NnF \c__htag_alphabet_str {##1} { \bool_set_true:N \l__htag_bad_bool } }
    \bool_if:NT \l__htag_bad_bool { \msg_warning:nnnn { htag } { bad-form } {#1} {#2} }
  }
\cs_generate_variant:Nn \__htag_check_form:nn { nx }

% ---------------------------------------------------------------- registry

% a registry line {tag}{label}; both arguments are strings
\cs_new_protected:Npn \__htag_store:nn #1#2
  {
    \seq_gput_right:Nn \g__htag_entries_seq { {#1} {#2} }
    \tl_if_empty:nF {#2}
      {
        \prop_if_in:NnF \g__htag_reg_tag_prop {#2}
          { \prop_gput:Nnn \g__htag_reg_tag_prop {#2} {#1} }
      }
    \prop_get:NnNF \g__htag_reg_labels_prop {#1} \l__htag_tmp_tl
      { \tl_clear:N \l__htag_tmp_tl }
    \tl_put_right:Nn \l__htag_tmp_tl { {#2} }
    \prop_gput:NnV \g__htag_reg_labels_prop {#1} \l__htag_tmp_tl
  }
\cs_generate_variant:Nn \__htag_store:nn { xx }

% a new line for the registry; the lookup tables stay as read, so that
% every item of this run is checked against the registry of the last run
\cs_new_protected:Npn \__htag_add:nn #1#2
  {
    \prop_get:NnNF \g__htag_reg_labels_prop {#1} \l__htag_tmp_tl
      { \tl_clear:N \l__htag_tmp_tl }
    \__htag_if_listed:nVF {#2} \l__htag_tmp_tl
      {
        \seq_gput_right:Nn \g__htag_entries_seq { {#1} {#2} }
        \bool_gset_true:N \g__htag_changed_bool
      }
  }
\cs_generate_variant:Nn \__htag_add:nn { VV }

% is string #1 one of the items of the list #2 = {a}{b}...?
\prg_new_protected_conditional:Npnn \__htag_if_listed:nn #1#2 { F , TF }
  {
    \bool_set_false:N \l_tmpa_bool
    \tl_map_inline:nn {#2}
      { \str_if_eq:nnT {##1} {#1} { \bool_set_true:N \l_tmpa_bool \tl_map_break: } }
    \bool_if:NTF \l_tmpa_bool { \prg_return_true: } { \prg_return_false: }
  }
\prg_generate_conditional_variant:Nnn \__htag_if_listed:nn { nV , VV } { F , TF }

% 'label `x'', or 'a tag without label', for messages
\cs_new:Npn \__htag_owner:n #1
  { \tl_if_empty:nTF {#1} { a~tag~without~label } { label~`#1' } }

% the commands the registry file is made of
\NewDocumentCommand \htagregistrysalt { m }
  { \str_gset:Nx \g__htag_reg_salt_str { \tl_to_str:n {#1} } }
\NewDocumentCommand \htagentry { m m }
  { \__htag_store:xx { \tl_to_str:n {#1} } { \tl_to_str:n {#2} } }

\cs_new_protected:Npn \__htag_read_registry:
  {
    \file_if_exist:nT { \g__htag_file_str }
      {
        \bool_gset_true:N \g__htag_found_bool
        \file_input:n { \g__htag_file_str }
      }
  }

\cs_new_protected:Npn \__htag_write_registry:
  {
    \seq_gsort:Nn \g__htag_entries_seq
      {
        \str_compare:nNnTF {##1} > {##2}
          { \sort_return_swapped: } { \sort_return_same: }
      }
    \iow_open:Nn \g__htag_iow { \g__htag_file_str }
    \iow_now:Nx \g__htag_iow
      {
        \c_percent_str \c_space_tl htag~registry:~the~salt~and~every~tag~shown~
        in~this~document,~with~its~label.
      }
    \iow_now:Nx \g__htag_iow
      {
        \c_percent_str \c_space_tl Rewritten~by~htag.sty~when~a~tag~is~added.~
        Commit~it;~never~edit~or~delete~it.
      }
    \iow_now:Nx \g__htag_iow
      { \token_to_str:N \htagregistrysalt { \g__htag_salt_str } }
    \seq_map_inline:Nn \g__htag_entries_seq
      { \iow_now:Nx \g__htag_iow { \token_to_str:N \htagentry ##1 } }
    \iow_close:N \g__htag_iow
  }

% ---------------------------------------------------------------- document

% 'on input line N' for messages, as LaTeX itself reports positions
\cs_new:Npn \__htag_here: { on~input~line~ \int_use:N \tex_inputlineno:D }

% 'file:line' for the index (the kernel's \CurrentFile goes stale after
% \include, so the package keeps its own stack of open files)
\cs_new:Npn \__htag_source:
  {
    \seq_if_empty:NTF \g__htag_files_seq
      { \g__htag_main_str } { \seq_item:Nn \g__htag_files_seq { 1 } }
    \c_colon_str \int_use:N \tex_inputlineno:D
  }

% record the page an item lands on; read back from the .aux on the next run
\cs_new_protected:Npn \__htag_note_page:n #1
  {
    \legacy_if:nT { @filesw }
      { \protected@write \@mainaux { } { \string \htag@page {#1} { \thepage } } }
  }

% record the printed number of environment #1, unless it stepped no counter
\cs_new_protected:Npn \__htag_note_number:n #1
  {
    \prop_if_in:NnF \g__htag_number_prop {#1}
      {
        \bool_lazy_and:nnTF
          { \tl_if_eq_p:NN \@currentlabel \l__htag_prevlabel_tl }
          { \tl_if_eq_p:NN \@currentcounter \l__htag_prevcounter_tl }
          { \prop_gput:Nnn \g__htag_number_prop {#1} { - } }
          {
            \protected@edef \l__htag_tmp_tl { \@currentlabel }
            \prop_gput:Nnx \g__htag_number_prop {#1} { \tl_to_str:N \l__htag_tmp_tl }
          }
      }
  }

% start of a listed environment
\cs_new_protected:Npn \__htag_begin:
  {
    \int_gincr:N \g__htag_occ_int
    \tl_set:Nx \l__htag_current_tl { \int_use:N \g__htag_occ_int }
    \tl_set_eq:NN \l__htag_env_tl \@currenvir
    \prop_gput:Nxx \g__htag_where_prop { \l__htag_current_tl }
      { \@currenvir \c_space_tl \__htag_here: }
    \seq_gput_right:NV \g__htag_items_seq \l__htag_current_tl
    \prop_gput:NVx \g__htag_envname_prop \l__htag_current_tl { \@currenvir }
    \prop_gput:NVx \g__htag_source_prop \l__htag_current_tl { \__htag_source: }
    \tl_set_eq:NN \l__htag_prevlabel_tl \@currentlabel
    \tl_set_eq:NN \l__htag_prevcounter_tl \@currentcounter
    \int_set:Nn \l__htag_level_int { \tex_currentgrouplevel:D }
    \prop_gput:NVx \g__htag_level_prop \l__htag_current_tl { \int_use:N \l__htag_level_int }
    % no margin note can go into a float or a minipage
    \bool_lazy_or:nnT
      { \cs_if_exist_p:N \@captype }
      { ! \tl_if_eq_p:NN \@mpfn \c__htag_footnote_tl }
      { \prop_gput:NVn \g__htag_boxed_prop \l__htag_current_tl { } }
    % show the tag when the environment's first paragraph starts; right after
    % a run-in heading (amsart's \subsection), the environment first starts
    % the heading's paragraph, which is skipped
    \legacy_if:nT { @noskipsec }
      { \prop_gput:NVn \g__htag_runin_prop \l__htag_current_tl { } }
    \exp_args:Nnx \AddToHookNext { para/begin }
      { \__htag_show:n { \l__htag_current_tl } }
  }

% end of a listed environment: it must have a \label or a pinned tag
\cs_new_protected:Npn \__htag_end:
  {
    \bool_lazy_or:nnF
      { \prop_if_in_p:NV \g__htag_label_prop \l__htag_current_tl }
      { \prop_if_in_p:NV \g__htag_pinned_prop \l__htag_current_tl }
      {
        \__htag_error:nxxxx { no-label }
          { \prop_item:NV \g__htag_where_prop \l__htag_current_tl } { } { } { }
      }
    % an environment none of whose paragraphs could take the tag: show it now
    \prop_gremove:NV \g__htag_runin_prop \l__htag_current_tl
    \prop_if_in:NVF \g__htag_shown_prop \l__htag_current_tl
      {
        \legacy_if:nT { @inlabel } { \mode_leave_vertical: }
        \exp_args:NV \__htag_show_now:n \l__htag_current_tl
      }
  }

% the tag to typeset for environment #1, into token list #2: its pinned tag;
% else, if its label is known, the label's tag on the last run, or else the
% tag computed from the label; else its tag on the last run; else ????
\cs_new_protected:Npn \__htag_display:nN #1#2
  {
    \prop_get:NnNF \g__htag_pinned_prop {#1} #2
      {
        \prop_get:NnNTF \g__htag_label_prop {#1} \l__htag_label_tl
          {
            \prop_get:NVNF \g__htag_bylabel_prop \l__htag_label_tl #2
              { \__htag_tag_of:VN \l__htag_label_tl #2 }
          }
          {
            \prop_get:NnNF \g__htag_byocc_prop {#1} #2
              { \tl_set:Nn #2 { ???? } }
          }
      }
  }

% a paragraph starts and environment #1 has not shown its tag: show it here,
% unless the paragraph is that of a run-in heading, or lies in a box inside
% the environment (a footnote in its title, a figure, a \marginpar); then
% wait for the next paragraph. The environment's own paragraphs lie at most
% one group deeper than its \begin (lists and displays open one group).
\cs_new_protected:Npn \__htag_show:n #1
  {
    \prop_if_in:NnF \g__htag_shown_prop {#1}
      {
        \bool_lazy_or:nnTF
          { \prop_if_in_p:Nn \g__htag_runin_prop {#1} }
          {
            \bool_lazy_and_p:nn
              { ! \prop_if_in_p:Nn \g__htag_boxed_prop {#1} }
              {
                \bool_lazy_or_p:nn
                  {
                    \int_compare_p:nNn { \tex_currentgrouplevel:D }
                      > { \prop_item:Nn \g__htag_level_prop {#1} + 1 }
                  }
                  {
                    \bool_lazy_or_p:nn
                      { \cs_if_exist_p:N \@captype }
                      { ! \tl_if_eq_p:NN \@mpfn \c__htag_footnote_tl }
                  }
              }
          }
          {
            \prop_gremove:Nn \g__htag_runin_prop {#1}
            \AddToHookNext { para/begin } { \__htag_show:n {#1} }
          }
          { \__htag_show_now:n {#1} }
      }
  }
\cs_new_protected:Npn \__htag_show_now:n #1
  {
    \prop_if_in:NnF \g__htag_shown_prop {#1}
      {
        \__htag_note_page:n {#1}
        \__htag_note_number:n {#1}
        \__htag_display:nN {#1} \l__htag_tmp_tl
        \prop_gput:NnV \g__htag_shown_prop {#1} \l__htag_tmp_tl
        \tl_if_empty:NF \l__htag_tmp_tl
          {
            \prop_if_in:NnTF \g__htag_boxed_prop {#1}
              {
                \msg_warning:nnxx { htag } { not-shown }
                  { \prop_item:Nn \g__htag_where_prop {#1} } { \l__htag_tmp_tl }
              }
              { \exp_args:NV \__htag_mark:n \l__htag_tmp_tl }
          }
      }
  }

% every \label: the first one directly inside a listed environment is its key
\cs_new_protected:Npn \__htag_label:n #1
  {
    \tl_if_empty:NF \l__htag_current_tl
      {
        \bool_lazy_and:nnT
          { \tl_if_eq_p:NN \@currenvir \l__htag_env_tl }
          { \int_compare_p:nNn { \tex_currentgrouplevel:D } < { \l__htag_level_int + 2 } }
          {
            \prop_if_in:NVF \g__htag_label_prop \l__htag_current_tl
              {
                \prop_gput:NVx \g__htag_label_prop \l__htag_current_tl { \tl_to_str:n {#1} }
                \exp_args:NV \__htag_note_number:n \l__htag_current_tl
              }
          }
      }
  }

% kernels before 2023-11 have no label hook: wrap \label instead
\cs_new_protected:Npn \__htag_wrap_label:
  {
    \NewCommandCopy \__htag_orig_label:w \label
    \DeclareRobustCommand \label
      { \peek_meaning:NTF [ \__htag_label_opt:w \__htag_label_noopt:n }
  }
\cs_new_protected:Npn \__htag_label_opt:w [ #1 ] #2
  { \__htag_label:n {#2} \__htag_orig_label:w [ #1 ] {#2} }
\cs_new_protected:Npn \__htag_label_noopt:n #1
  { \__htag_label:n {#1} \__htag_orig_label:w {#1} }

% \htag{XXXX} written by hand (never empty here)
\cs_new_protected:Npn \__htag_pinned:n #1
  {
    \tl_if_empty:NTF \l__htag_current_tl
      {
        \tl_set:Nx \l__htag_where_tl
          { \token_to_str:N \htag \c_space_tl \__htag_here: }
        \__htag_check_form:nx {#1} { \l__htag_where_tl }
        \__htag_section_tag:n {#1}
        \int_gincr:N \g__htag_free_int
        \tl_set:Nx \l__htag_item_tl { s \int_use:N \g__htag_free_int }
        \seq_gput_right:NV \g__htag_items_seq \l__htag_item_tl
        \prop_gput:NVn \g__htag_final_prop \l__htag_item_tl {#1}
        \prop_gput:NVn \g__htag_envname_prop \l__htag_item_tl { - }
        \prop_gput:NVn \g__htag_number_prop \l__htag_item_tl { - }
        \prop_gput:NVx \g__htag_source_prop \l__htag_item_tl { \__htag_source: }
        \legacy_if:nT { @inlabel } { \mode_leave_vertical: }
        \__htag_mark:n {#1}
        \exp_args:NV \__htag_note_page:n \l__htag_item_tl
      }
      {
        \__htag_check_form:nx {#1}
          { \prop_item:NV \g__htag_where_prop \l__htag_current_tl }
        \prop_gput:NVn \g__htag_pinned_prop \l__htag_current_tl {#1}
      }
  }

% a tag outside listed environments: not one a label had, not twice
\cs_new_protected:Npn \__htag_section_tag:n #1
  {
    \prop_gput:Nnn \g__htag_used_prop {#1} { }
    \prop_get:NnNTF \g__htag_reg_labels_prop {#1} \l__htag_owners_tl
      {
        \tl_map_inline:Nn \l__htag_owners_tl
          {
            \tl_if_empty:nF {##1}
              {
                \__htag_free_tag:nN {#1} \l__htag_free_tl
                \__htag_error:nxxxx { reused } {#1} { label~`##1' }
                  { \l__htag_where_tl } { \l__htag_free_tl }
                \tl_map_break:
              }
          }
      }
      { }
    \__htag_claim:nnn {#1} { \l__htag_where_tl } {#1}
    \__htag_add:nn {#1} { }
  }

% tag #1 appears at #2; error if it already appeared in this run;
% #3 is the key for suggesting a free tag
\cs_new_protected:Npn \__htag_claim:nnn #1#2#3
  {
    \prop_get:NnNTF \g__htag_inrun_prop {#1} \l__htag_tmp_tl
      {
        \bool_set_true:N \l__htag_dup_bool
        \__htag_free_tag:nN {#3} \l__htag_free_tl
        \__htag_error:nxxxx { duplicate } {#1} { \l__htag_tmp_tl } {#2} { \l__htag_free_tl }
      }
      { \prop_gput:Nnx \g__htag_inrun_prop {#1} {#2} }
  }

\cs_new_protected:Npn \__htag_label_of:nN #1#2
  { \prop_get:NnNF \g__htag_label_prop {#1} #2 { \tl_clear:N #2 } }

% ---------------------------------------------------------------- end

\cs_new_protected:Npn \__htag_finish:
  {
    % the tag of every listed environment
    \int_step_inline:nn { \g__htag_occ_int }
      {
        \prop_get:NnNF \g__htag_pinned_prop {##1} \l__htag_tag_tl
          {
            \__htag_label_of:nN {##1} \l__htag_label_tl
            \tl_if_empty:NTF \l__htag_label_tl
              { \tl_clear:N \l__htag_tag_tl }
              { \__htag_tag_of:VN \l__htag_label_tl \l__htag_tag_tl }
          }
        \prop_gput:NnV \g__htag_final_prop {##1} \l__htag_tag_tl
        \tl_if_empty:NF \l__htag_tag_tl
          { \prop_gput:NVn \g__htag_used_prop \l__htag_tag_tl { } }
        \__htag_label_of:nN {##1} \l__htag_label_tl
        \tl_if_empty:NF \l__htag_label_tl
          { \prop_gput:NVn \g__htag_doclabels_prop \l__htag_label_tl { } }
      }
    \int_step_inline:nn { \g__htag_occ_int } { \__htag_check:n {##1} }
    \bool_if:NT \g__htag_rerun_bool { \msg_warning:nn { htag } { rerun } }
    \bool_if:NF \g__htag_error_bool
      {
        \bool_if:NT \g__htag_changed_bool
          {
            \legacy_if:nT { @filesw }
              {
                \__htag_write_registry:
                \bool_if:NF \g__htag_found_bool
                  { \msg_warning:nnx { htag } { new-registry } { \g__htag_file_str } }
              }
          }
      }
    \legacy_if:nT { @filesw } { \__htag_write_index: }
  }

% environment no. #1: check its tag, record it, and pass it to the next run
\cs_new_protected:Npn \__htag_check:n #1
  {
    \prop_get:NnN \g__htag_final_prop {#1} \l__htag_tag_tl
    \__htag_label_of:nN {#1} \l__htag_label_tl
    \tl_set:Nx \l__htag_where_tl
      {
        \prop_item:Nn \g__htag_where_prop {#1}
        \tl_if_empty:NF \l__htag_label_tl { \c_space_tl (label~`\l__htag_label_tl') }
      }
    \bool_set:Nn \l__htag_pinned_bool { \prop_if_in_p:Nn \g__htag_pinned_prop {#1} }
    \bool_set_false:N \l__htag_dup_bool
    \tl_if_empty:NF \l__htag_tag_tl
      {
        % the same tag twice in this run; the one to pin is the item whose
        % label did not have the tag before
        \prop_get:NVNTF \g__htag_inrun_prop \l__htag_tag_tl \l__htag_tmp_tl
          {
            \bool_set_true:N \l__htag_dup_bool
            \prop_get:NVNF \g__htag_claimer_prop \l__htag_tag_tl \l__htag_other_tl
              { \tl_clear:N \l__htag_other_tl }
            \prop_get:NVNF \g__htag_reg_tag_prop \l__htag_label_tl \l__htag_key_tl
              { \tl_clear:N \l__htag_key_tl }
            \bool_lazy_and:nnTF
              { ! \tl_if_empty_p:N \l__htag_label_tl }
              { \str_if_eq_p:VV \l__htag_key_tl \l__htag_tag_tl }
              {
                \tl_if_empty:NTF \l__htag_other_tl
                  { \tl_set_eq:NN \l__htag_key_tl \l__htag_tmp_tl }
                  { \tl_set_eq:NN \l__htag_key_tl \l__htag_other_tl }
                \__htag_free_tag:VN \l__htag_key_tl \l__htag_free_tl
                \__htag_error:nxxxx { duplicate } { \l__htag_tag_tl } { \l__htag_where_tl }
                  { \l__htag_tmp_tl } { \l__htag_free_tl }
              }
              {
                \tl_if_empty:NTF \l__htag_label_tl
                  { \tl_set_eq:NN \l__htag_key_tl \l__htag_where_tl }
                  { \tl_set_eq:NN \l__htag_key_tl \l__htag_label_tl }
                \__htag_free_tag:VN \l__htag_key_tl \l__htag_free_tl
                \__htag_error:nxxxx { duplicate } { \l__htag_tag_tl } { \l__htag_tmp_tl }
                  { \l__htag_where_tl } { \l__htag_free_tl }
              }
          }
          {
            \prop_gput:NVV \g__htag_inrun_prop \l__htag_tag_tl \l__htag_where_tl
            \prop_gput:NVV \g__htag_claimer_prop \l__htag_tag_tl \l__htag_label_tl
          }
        % the label had another tag before
        \tl_if_empty:NF \l__htag_label_tl
          {
            \prop_get:NVNT \g__htag_reg_tag_prop \l__htag_label_tl \l__htag_tmp_tl
              {
                \str_if_eq:VVF \l__htag_tmp_tl \l__htag_tag_tl
                  {
                    \__htag_error:nxxxx { changed } { \l__htag_where_tl }
                      { \l__htag_tag_tl } { \l__htag_tmp_tl } { }
                  }
              }
          }
        % the tag belonged to another label before, one no longer in the
        % document (if it is still there, the duplicate error reports it)
        \bool_if:NF \l__htag_dup_bool
          {
            \prop_get:NVNT \g__htag_reg_labels_prop \l__htag_tag_tl \l__htag_owners_tl
              {
                \bool_set_false:N \l_tmpb_bool
                \tl_map_inline:Nn \l__htag_owners_tl
                  {
                    \prop_if_in:NnT \g__htag_doclabels_prop {##1}
                      { \bool_set_true:N \l_tmpb_bool }
                  }
                \__htag_if_listed:VVTF \l__htag_label_tl \l__htag_owners_tl
                  { \bool_set_true:N \l_tmpb_bool } { }
                \bool_if:NF \l_tmpb_bool
                  {
                    \tl_set:Nx \l__htag_tmp_tl
                      { \exp_args:Nf \__htag_owner:n { \tl_head:N \l__htag_owners_tl } }
                    \bool_if:NTF \l__htag_pinned_bool
                      {
                        \msg_warning:nnxxx { htag } { takeover }
                          { \l__htag_where_tl } { \l__htag_tag_tl } { \l__htag_tmp_tl }
                      }
                      {
                        \__htag_free_tag:VN \l__htag_label_tl \l__htag_free_tl
                        \__htag_error:nxxxx { retired } { \l__htag_where_tl }
                          { \l__htag_tag_tl } { \l__htag_tmp_tl } { \l__htag_free_tl }
                      }
                  }
              }
          }
        \__htag_add:VV \l__htag_tag_tl \l__htag_label_tl
      }
    % for the next run
    \legacy_if:nT { @filesw }
      {
        \iow_now:Nx \@mainaux { \token_to_str:N \htag@byocc {#1} { \l__htag_tag_tl } }
        \tl_if_empty:NF \l__htag_label_tl
          {
            \iow_now:Nx \@mainaux
              { \token_to_str:N \htag@bylabel { \l__htag_label_tl } { \l__htag_tag_tl } }
          }
      }
    \prop_get:NnNF \g__htag_shown_prop {#1} \l__htag_tmp_tl { \tl_clear:N \l__htag_tmp_tl }
    \str_if_eq:VVF \l__htag_tmp_tl \l__htag_tag_tl { \bool_gset_true:N \g__htag_rerun_bool }
  }

% ---------------------------------------------------------------- index

\cs_new:Npn \__htag_item:Nn #1#2
  { \prop_if_in:NnTF #1 {#2} { \prop_item:Nn #1 {#2} } { - } }
\cs_new:Npn \__htag_cell:nN #1#2
  { #1 \prg_replicate:nn { #2 - \str_count:n {#1} } { \c_space_tl } }
\cs_new:Npn \__htag_row:nnnnnn #1#2#3#4#5#6
  {
    | \c_space_tl \__htag_cell:nN {#1} \l__htag_wa_int
    \c_space_tl | \c_space_tl \__htag_cell:nN {#2} \l__htag_wb_int
    \c_space_tl | \c_space_tl \__htag_cell:nN {#3} \l__htag_wc_int
    \c_space_tl | \c_space_tl \__htag_cell:nN {#4} \l__htag_wd_int
    \c_space_tl | \c_space_tl \__htag_cell:nN {#5} \l__htag_we_int
    \c_space_tl | \c_space_tl \__htag_cell:nN {#6} \l__htag_wf_int
    \c_space_tl |
  }
\cs_new:Npn \__htag_rule:N #1 { \prg_replicate:nn { #1 + 2 } { - } | }
\cs_new_protected:Npn \__htag_widen:Nn #1#2
  { \int_set:Nn #1 { \int_max:nn {#1} { \str_count:n {#2} } } }
\cs_new_protected:Npn \__htag_widths:nnnnnn #1#2#3#4#5#6
  {
    \__htag_widen:Nn \l__htag_wa_int {#1}
    \__htag_widen:Nn \l__htag_wb_int {#2}
    \__htag_widen:Nn \l__htag_wc_int {#3}
    \__htag_widen:Nn \l__htag_wd_int {#4}
    \__htag_widen:Nn \l__htag_we_int {#5}
    \__htag_widen:Nn \l__htag_wf_int {#6}
  }

\cs_new_protected:Npn \__htag_write_index:
  {
    \seq_gclear:N \g__htag_rows_seq
    \seq_map_inline:Nn \g__htag_items_seq
      {
        \prop_get:NnNT \g__htag_final_prop {##1} \l__htag_tag_tl
          {
            \tl_if_empty:NF \l__htag_tag_tl
              {
                \seq_gput_right:Nx \g__htag_rows_seq
                  {
                    { \l__htag_tag_tl }
                    { \__htag_item:Nn \g__htag_envname_prop {##1} }
                    { \__htag_item:Nn \g__htag_number_prop {##1} }
                    {
                      \prop_if_in:NnTF \g__htag_page_prop {##1}
                        { \prop_item:Nn \g__htag_page_prop {##1} } { ? }
                    }
                    {
                      \prop_if_in:NnTF \g__htag_label_prop {##1}
                        { ` \prop_item:Nn \g__htag_label_prop {##1} ` } { - }
                    }
                    { ` \prop_item:Nn \g__htag_source_prop {##1} ` }
                  }
              }
          }
      }
    \int_zero:N \l__htag_wa_int  \int_zero:N \l__htag_wb_int
    \int_zero:N \l__htag_wc_int  \int_zero:N \l__htag_wd_int
    \int_zero:N \l__htag_we_int  \int_zero:N \l__htag_wf_int
    \__htag_widths:nnnnnn { tag } { environment } { number } { page } { label } { source }
    \seq_map_inline:Nn \g__htag_rows_seq { \__htag_widths:nnnnnn ##1 }

    \iow_open:Nn \g__htag_iow { \g__htag_index_str }
    \iow_now:Nx \g__htag_iow { \c_hash_str \c_space_tl Tags~in~ \g__htag_main_str }
    \iow_now:Nn \g__htag_iow { }
    \iow_now:Nx \g__htag_iow
      {
        Rewritten~by~htag.sty~on~every~compile:~the~tags~in~the~document~as~it~is~now.~
        Do~not~edit.~The~permanent~record~of~every~tag~shown~is~ \g__htag_file_str .
        \c_space_tl Pages~are~from~the~previous~compile,~like~\iow_char:N\\pageref.
      }
    \iow_now:Nn \g__htag_iow { }
    \iow_now:Nx \g__htag_iow
      { \__htag_row:nnnnnn { tag } { environment } { number } { page } { label } { source } }
    \iow_now:Nx \g__htag_iow
      {
        | \__htag_rule:N \l__htag_wa_int \__htag_rule:N \l__htag_wb_int
          \__htag_rule:N \l__htag_wc_int \__htag_rule:N \l__htag_wd_int
          \__htag_rule:N \l__htag_we_int \__htag_rule:N \l__htag_wf_int
      }
    \seq_map_inline:Nn \g__htag_rows_seq
      { \iow_now:Nx \g__htag_iow { \__htag_row:nnnnnn ##1 } }
    \iow_close:N \g__htag_iow
  }

% read from the .aux file
\cs_new_protected:Npn \htag@byocc #1#2
  { \prop_gput:Nnx \g__htag_byocc_prop {#1} { \tl_to_str:n {#2} } }
\cs_new_protected:Npn \htag@bylabel #1#2
  { \prop_gput:Nxx \g__htag_bylabel_prop { \tl_to_str:n {#1} } { \tl_to_str:n {#2} } }
\cs_new_protected:Npn \htag@page #1#2
  { \prop_gput:Nnx \g__htag_page_prop {#1} { \tl_to_str:n {#2} } }

% ---------------------------------------------------------------- user commands

\NewDocumentCommand \htagenvironments { m }
  {
    \bool_gset_true:N \g__htag_listed_bool
    \clist_map_inline:nn {#1}
      {
        \seq_if_in:NnF \g__htag_envs_seq {##1}
          {
            \seq_gput_right:Nn \g__htag_envs_seq {##1}
            \AddToHook { env/##1/begin } { \__htag_begin: }
            \AddToHook { env/##1/end } { \__htag_end: }
          }
      }
  }

\NewDocumentCommand \htagsalt { m }
  {
    \tl_set:Nn \l__htag_tmp_tl {#1}
    \tl_trim_spaces:N \l__htag_tmp_tl
    \str_gset:Nx \g__htag_salt_str { \tl_to_str:N \l__htag_tmp_tl }
  }
\@onlypreamble \htagsalt
\NewDocumentCommand \htagregistry { m } { \str_gset:Nn \g__htag_file_str {#1} }
\@onlypreamble \htagregistry
\NewDocumentCommand \htagindex { m } { \str_gset:Nn \g__htag_index_str {#1} }
\@onlypreamble \htagindex

\NewDocumentCommand \htag { m }
  {
    \tl_set:Nn \l__htag_tag_tl {#1}
    \tl_trim_spaces:N \l__htag_tag_tl
    \tl_if_empty:NF \l__htag_tag_tl
      { \exp_args:Nx \__htag_pinned:n { \tl_to_str:N \l__htag_tag_tl } }
    \tex_ignorespaces:D
  }

\NewDocumentCommand \htagmark { m } { \normalfont \footnotesize \ttfamily #1 }

% the margin note of a tag. Its content is a box, never a paragraph: the
% note is placed where an item's first paragraph starts, and a paragraph
% inside it there makes hyperref lose the item's link target
\cs_new_protected:Npn \__htag_mark:n #1
  { \marginpar { \hbox:n { \htagmark {#1} } } }

% ---------------------------------------------------------------- hooks

\AddToHook { begindocument/before }
  {
    \__htag_read_registry:
    \bool_if:NT \g__htag_listed_bool
      {
        \str_if_empty:NT \g__htag_salt_str
