% ---------------------------------------------------------------- subsections
% every item lies inside a numbered subsection: \ifhtp@insubsection is true from
% a numbered \subsection to the next \chapter, \section, \subsection* or \appendix
\newif\ifhtp@insubsection
\let\htp@section\section
\let\htp@subsection\subsection
\renewcommand{\section}{\global\htp@insubsectionfalse\htp@section}
\renewcommand{\subsection}{\@ifstar
  {\global\htp@insubsectionfalse\htp@subsection*}
  {\global\htp@insubsectiontrue\htp@subsection}}
\newcommand*{\htp@checksubsection}{%
  \ifhtp@insubsection\else
    \ClassError{htag_paper}{\@currenvir\space on input line \the\inputlineno\space
      is not inside a numbered subsection}{Every numbered item lies inside a
      \protect\subsection, so that it is numbered chapter.section.subsection.item.}%
  \fi}

% ---------------------------------------------------------------- numbered items
% \newitem{name}{Title} declares a numbered item in the current \theoremstyle;
% all items share one counter, reset in each subsection, and every item gets a
% margin tag and must lie inside a numbered subsection
\newcommand*{\htp@rules}[1]{%
  \htagenvironments{#1}%
  \AddToHook{env/#1/begin}{\htp@checksubsection}}
\newtheorem{theorem}{Theorem}[subsection]
\htp@rules{theorem}
\newcommand*{\newitem}[2]{\newtheorem{#1}[theorem]{#2}\htp@rules{#1}}
\newitem{proposition}{Proposition}
\newitem{lemma}{Lemma}
\newitem{corollary}{Corollary}
\newitem{conjecture}{Conjecture}
