% ---------------------------------------------------------------- chapters
% chapters number sections and equations; after \appendix they are A, B, ...,
% with link targets apart from those of chapters 1, 2, ...
\newcounter{chapter}
\counterwithin{section}{chapter}
\numberwithin{equation}{chapter}
\newcommand{\htp@head}[1]{%
  \vspace*{10\p@}%
  {\parindent\z@ \raggedright \normalfont \interlinepenalty\@M
   \Large\bfseries #1\par\nobreak \vskip 16\p@}%
  \@afterheading}
\def\htp@chapter[#1]#2{%
  \clearpage
  \global\htp@insubsectionfalse
