#!/usr/bin/env python3
r"""
Cross-reference audit of the document. Part of hashtag: do not edit.

hyperref does not warn about every missing \ref target, and a duplicated \label silently makes one of two
references point at the wrong item. This script checks the sources independently, after a full build.

It reads manuscript/main.tex and every file it inputs (\input, \include), in order, and manuscript/main.aux:
  1. every \ref, \eqref and \pageref target is defined;
  2. no \label is defined twice;
  3. every numbered item has its \label right after \begin{...} and its optional title (after \htag{...}, if
     the item pins its tag);
  4. every numbered item lies inside a numbered subsection;
  5. the items that are never referenced (for information only).
The numbered items are the environments the class declares and those the document declares with \newitem.
Exit status 1 if one of checks 1-4 fails.
"""
import os, re, sys

ENVS = ('theorem proposition lemma corollary conjecture hypothesis definition construction notation example '
        'counterexample variant experiment remark warning question heuristic').split()

here = os.path.dirname(os.path.abspath(__file__))
man = os.path.normpath(os.path.join(here, '..', 'manuscript'))


def strip_comments(s):
    """Drop what LaTeX never reads: comments (a % after an even number of backslashes), comment
    environments and \\iffalse ... \\fi blocks."""
    s = re.sub(r'(?<!\\)((?:\\\\)*)%.*', r'\1', s)
    s = re.sub(r'\\begin\{comment\}.*?\\end\{comment\}', '', s, flags=re.S)
    return re.sub(r'\\iffalse\b.*?\\fi\b', '', s, flags=re.S)


def resolve(name):
    for cand in (name, name + '.tex'):
        p = os.path.join(man, cand)
        if os.path.isfile(p):
            return p
    return None


INPUT = re.compile(r'\\(input|include)\{([^}]*)\}')


def event_re(envs):
    """Inputs, headings and the \\begin of numbered items."""
    return re.compile(INPUT.pattern + r'|\\(chapter|section|subsection)(\*?)\s*(?:\[[^\]]*\]\s*)?\{|'
                      r'\\begin\{(' + '|'.join(re.escape(e) for e in envs) + r')\}')


def read_all(name, seen, texts):
    """The text of a file and, recursively, of the files it inputs."""
    path = resolve(name)
    if path is None or path in seen:
        return
    seen.add(path)
    s = strip_comments(open(path, encoding='utf-8').read())
    texts.append(s)
    for m in INPUT.finditer(s):
        read_all(m.group(2), seen, texts)


def walk(name, event, files, events, seen):
    """Read a file and, recursively and in order, the files it inputs."""
    path = resolve(name)
    if path is None or path in seen:
        return
    seen.add(path)
    s = strip_comments(open(path, encoding='utf-8').read())
    files.append((path, s))
    for m in event.finditer(s):
        where = '%s:%d' % (os.path.relpath(path, man), s.count('\n', 0, m.start()) + 1)
        if m.group(1):
            walk(m.group(2), event, files, events, seen)
        elif m.group(3):
            events.append(('heading', m.group(3) + m.group(4), where, None))
        else:
            events.append(('item', m.group(5), where, label_after(s, m.end())))


def label_after(s, i):
    """The label right after \\begin{env} at position i: skip the optional title and \\htag{...}."""
    n = len(s)
    while i < n and s[i].isspace():
        i += 1
    if i < n and s[i] == '[':            # optional title: brackets inside braces do not count
        depth, i = 0, i + 1
        while i < n and not (s[i] == ']' and depth == 0):
            if s[i] == '\\':
                i += 1
            elif s[i] == '{':
                depth += 1
            elif s[i] == '}':
                depth -= 1
            i += 1
        i += 1
    m = re.compile(r'\s*(?:\\htag\{[^}]*\}\s*)?\\label\{([^}]*)\}').match(s, i)
    return m.group(1) if m else None


def main():
    texts = []
    read_all('main', set(), texts)
    envs = ENVS + re.findall(r'\\newitem\s*\{([^}]*)\}', '\n'.join(texts))
    files, events = [], []
    walk('main', event_re(envs), files, events, set())
    if not files:
        print('FAIL manuscript/main.tex not found')
        return 1
    aux_path = os.path.join(man, 'main.aux')
    if not os.path.exists(aux_path):
        print('FAIL manuscript/main.aux not found: build first')
        return 1
    aux, todo, read = '', ['main.aux'], set()
    while todo:                          # main.aux and the .aux files of \include'd chapters
        name = todo.pop()
        p = os.path.join(man, name)
        if name in read or not os.path.exists(p):
            continue
        read.add(name)
        text = open(p, encoding='utf-8', errors='replace').read()
        aux += text
        todo += re.findall(r'\\@input\{([^}]*)\}', text)
    tex = '\n'.join(s for _, s in files)

    refs = {r for r in re.findall(r'\\(?:eq|page)?ref\*?\{([^}]*)\}', tex) if '#' not in r}
    defined = set(re.findall(r'\\newlabel\{([^}]*)\}', aux))
    labels = re.findall(r'\\label\{([^}]*)\}', tex)
    seen, dups = set(), set()
    for l in labels:
        (dups if l in seen else seen).add(l)

    unlabelled, outside, level = [], [], None
    items = [e for e in events if e[0] == 'item']
    for kind, name, where, label in events:
        if kind == 'heading':
            level = name
        else:
            if label is None:
                unlabelled.append('%s %s' % (name, where))
            if level != 'subsection':
                outside.append('%s %s' % (name, where))

    fail = 0

    def report(name, bad):
        nonlocal fail
        if bad:
            fail = 1
            print('FAIL %-36s %s' % (name, ', '.join(sorted(bad)[:12]) + (' ...' if len(bad) > 12 else '')))
        else:
            print('PASS %s' % name)

    report('every reference is defined', refs - defined)
    report('no label is defined twice', dups)
    report('every item has a label', unlabelled)
    report('every item lies in a subsection', outside)
    item_labels = {label for _, _, _, label in items if label}
    print('     %d numbered items, %d distinct references, %d items never referenced'
          % (len(items), len(refs), len(item_labels - refs)))
    return fail


if __name__ == '__main__':
    sys.exit(main())

